function rankingScheduleText(r,m,now=Date.now()){
 if(!m.online)return 'รอเชื่อมต่อเพื่ออัปเดตอันดับ';
 if(!m.detailsFresh)return 'รอข้อมูลตัวละครสด';
 if(!Number.isFinite(r.nextUpdateAt))return 'ยังไม่ทราบรอบอัปเดต';
 if(r.nextUpdateAt<=now)return 'เลยกำหนดอัปเดต · รอผลจากเซิร์ฟเวอร์';
 return 'รอบถัดไป '+new Date(r.nextUpdateAt).toLocaleTimeString('th-TH');
}
