 const overall=roster.map(m=>m.details?.serverRankings?.categories?.overall).filter(Boolean).map(r=>({...r,fresh:Date.now()-r.receivedAt>=-5000&&Date.now()-r.receivedAt<=360000})).sort((a,b)=>b.receivedAt-a.receivedAt)[0];
 const leaders=overall?.leaders||[];
 updateFleetDOM(host,'<h3>อันดับทั้งเซิร์ฟเวอร์ · เป้าหมาย Top 10</h3><p class="subtle">อันดับจริงจากเซิร์ฟเวอร์ แยก 5 หมวด · เกมจัดอันดับใหม่ทุก 5 นาที · กราฟสูงขึ้นหมายถึงอันดับดีขึ้น<br>อันดับรวมใช้ทั้งพลัง เลเวล เงิน และนักสะสม เงินนับที่ถืออยู่ จึงต้องรักษางบอัปเกรดด้วย</p>'+table(['ตัวละคร','รวม','พลัง','เลเวล','เงิน','สะสม','ถึงเป้าหมาย','แนวโน้ม','เวลา / จำนวนผู้เล่น'],rows)+(leaders.length?'<details><summary>เทียบหัวตารางอันดับรวม 10 คนแรก'+(overall.fresh?'':' · ข้อมูลเก่า')+'</summary>'+table(['อันดับ','ชื่อ','เลเวล','คะแนน'],leaders.map(r=>[fmt(r.pos),esc(r.name),fmt(r.lv),esc(r.v)]))+'</details>':'<p class="muted">กำลังรอการตอบอันดับจากเซิร์ฟเวอร์ ไม่ใช้ตัวเลขในภาพแทนข้อมูลจริง</p>'));
